import{_ as t,o,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Jewel -- Sloppy Reads","description":"","frontmatter":{"title":"CDS Jewel -- Sloppy Reads","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","分布式存储","读取延迟","一致性模型","快照","数据保护"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Sloppy_Reads.md","filePath":"posts/2015/CDS_Jewel_--_Sloppy_Reads.md","lastUpdated":1780459816000}'),i={name:"posts/2015/CDS_Jewel_--_Sloppy_Reads.md"};function p(r,l,n,_,a,g){return o(),e("div",null,[...l[0]||(l[0]=[s("<p>Ceph存储系统性能优化与一致性模型讨论会议纪要：</p><p>一、会议关键细节</p><ol><li>近期对降低读取延迟的需求增加，尤其是在特定场景下，如创建唯一名称且不修改的对象，允许读取可能有益。</li><li>讨论了在特定场景下，允许客户端从非活动OSD读取数据以减少延迟的可能性。</li><li>分析了现有架构对延迟保证的挑战，例如无法保证已看到所有对客户端提交的权利，需要阻塞读取直到OSD恢复。</li><li>讨论了引入新的存储池类型或参数以支持从非活动OSD读取数据。</li><li>讨论了对于需要使用快照的场景，如何保证读取的一致性。</li></ol><p>二、讨论的主要议题</p><ol><li><strong>读取延迟优化</strong>：讨论了在不同场景下如何优化读取延迟，包括使用非活动OSD读取数据等。</li><li><strong>一致性模型</strong>：讨论了Ceph当前的一致性模型，以及如何支持多种一致性级别。</li><li><strong>快照一致性</strong>：讨论了在快照场景下如何保证读取的一致性。</li><li><strong>数据保护</strong>：讨论了在优化读取性能时，如何保护数据一致性不被破坏。</li></ol><p>三、决定的事项</p><ol><li><strong>读取优化</strong>：将考虑引入新的存储池类型或参数，以支持从非活动OSD读取数据。</li><li><strong>一致性模型</strong>：将探索支持多种一致性级别的方法，但可能需要重新设计部分系统。</li><li><strong>快照一致性</strong>：将研究在快照场景下保证读取一致性的方法。</li></ol><p>四、后续行动计划</p><ol><li><strong>读取优化</strong>：Sam将研究如何实现从非活动OSD读取数据的功能，并与其他成员讨论实现细节。</li><li><strong>一致性模型</strong>：Ron将研究如何支持多种一致性级别，并与其他成员讨论实现方案。</li><li><strong>快照一致性</strong>：Mia将研究在快照场景下保证读取一致性的方法，并与其他成员讨论实现细节。</li><li><strong>数据保护</strong>：所有成员将共同讨论在优化读取性能时，如何保护数据一致性不被破坏。</li></ol>",9)])])}const c=t(i,[["render",p]]);export{d as __pageData,c as default};
